Rules.InvariantScript:
Set(varShowApproveAllConfirm, false);
Set(varShowAllWeeks, false);
Set(varWeeklyEmployeeEmail, "");
Set(varWeeklyEmployeeName, "");
Reset(Dropdown_Employee_Weekly);

Select(btn_ReloadWeekly);

If(
    !IsBlank(Trim(Self.SearchText)),
    ShowColumns(
        Office365Users.SearchUser(
            {
                searchTerm: Trim(Self.SearchText),
                top: 15
            }
        ),
        Id,
        DisplayName,
        Mail,
        UserPrincipalName,
        Department
    )
)

Set(
    varWeeklyEmployeeEmail,
    Lower(Coalesce(Self.Selected.Mail, Self.Selected.UserPrincipalName))
);
Set(varWeeklyEmployeeName, Self.Selected.DisplayName);
Select(btn_ReloadWeekly);

If(
    varWeeklySortColumn = "Employee_Name",
    Set(varWeeklySortAscending, !varWeeklySortAscending),
    Set(varWeeklySortColumn, "Employee_Name");
    Set(varWeeklySortAscending, true)
)

If(
    varWeeklySortColumn = "WeekStart",
    Set(varWeeklySortAscending, !varWeeklySortAscending),
    Set(varWeeklySortColumn, "WeekStart");
    Set(varWeeklySortAscending, false)
)

If(
    varWeeklySortColumn = "TotalStandard",
    Set(varWeeklySortAscending, !varWeeklySortAscending),
    Set(varWeeklySortColumn, "TotalStandard");
    Set(varWeeklySortAscending, false)
)

If(
    varWeeklySortColumn = "TotalDays",
    Set(varWeeklySortAscending, !varWeeklySortAscending),
    Set(varWeeklySortColumn, "TotalDays");
    Set(varWeeklySortAscending, false)
)

If(
    varWeeklySortColumn = "WeekStatus",
    Set(varWeeklySortAscending, !varWeeklySortAscending),
    Set(varWeeklySortColumn, "WeekStatus");
    Set(varWeeklySortAscending, true)
)

Clear(colRowActionIds);
If(
    varIsSuperAdmin,
    Collect(
        colRowActionIds,
        Filter(
            'Hours Tracking (Hours)',
            Employee = ThisItem.Employee &&
            Date >= ThisItem.WeekStart &&
            Date <= ThisItem.WeekEnd
        )
    ),
    Collect(
        colRowActionIds,
        Filter(
            'Hours Tracking (Hours)',
            Employee = ThisItem.Employee &&
            ApproverID_1 = User().Email &&
            Date >= ThisItem.WeekStart &&
            Date <= ThisItem.WeekEnd
        )
    )
);
ClearCollect(
    colRowActionIds,
    ForAll(
        Filter(colRowActionIds, ApprovalStatus_1 <> "Draft") As TargetRow,
        {
            ID: TargetRow.ID,
            ApprovalStatus_1: "Approved"
        }
    )
);
Patch('Hours Tracking (Hours)', colRowActionIds);
Clear(colRowActionIds);
Notify("Week approved", NotificationType.Success);
Select(btn_ReloadWeekly);

Clear(colRowActionIds);
If(
    varIsSuperAdmin,
    Collect(
        colRowActionIds,
        Filter(
            'Hours Tracking (Hours)',
            Employee = ThisItem.Employee &&
            Date >= ThisItem.WeekStart &&
            Date <= ThisItem.WeekEnd
        )
    ),
    Collect(
        colRowActionIds,
        Filter(
            'Hours Tracking (Hours)',
            Employee = ThisItem.Employee &&
            ApproverID_1 = User().Email &&
            Date >= ThisItem.WeekStart &&
            Date <= ThisItem.WeekEnd
        )
    )
);
ClearCollect(
    colRowActionIds,
    ForAll(
        Filter(colRowActionIds, ApprovalStatus_1 <> "Draft") As TargetRow,
        {
            ID: TargetRow.ID,
            ApprovalStatus_1: "Rejected"
        }
    )
);
Patch('Hours Tracking (Hours)', colRowActionIds);
Clear(colRowActionIds);
Notify("Week rejected", NotificationType.Warning);
Select(btn_ReloadWeekly);

Set(varSelectedWeekEmployee, ThisItem.Employee);
Set(varSelectedWeekEmployeeName, ThisItem.Employee_Name);
Set(varApprovalWeekStart, ThisItem.WeekStart);
Set(varDrillFromWeekly, true);
Navigate(Approvals, ScreenTransition.Cover);

ClearCollect(
    colApproveAllWeeks,
    ForAll(
        Filter(
            colAllPendingHours,
            ApprovalStatus_1 = "Pending" &&
            (
                IsBlank(varWeeklyEmployeeEmail) ||
                Lower(Employee) = varWeeklyEmployeeEmail
            ) &&
            (
                IsBlank(DatePicker_WeeklyFrom.SelectedDate) ||
                IsBlank(DatePicker_WeeklyTo.SelectedDate) ||
                (
                    DateAdd(Date, -(Weekday(Date, StartOfWeek.Monday) - 1), "Days") <= DatePicker_WeeklyTo.SelectedDate &&
                    DateAdd(DateAdd(Date, -(Weekday(Date, StartOfWeek.Monday) - 1), "Days"), 6, "Days") >= DatePicker_WeeklyFrom.SelectedDate
                )
            )
        ) As TargetRow,
        {
            ID: TargetRow.ID,
            ApprovalStatus_1: "Approved"
        }
    )
);
If(
    CountRows(colApproveAllWeeks) = 0,
    Notify("No pending timesheets in this filter", NotificationType.Information),
    Patch('Hours Tracking (Hours)', colApproveAllWeeks);
    Notify("All pending timesheets approved", NotificationType.Success)
);
Clear(colApproveAllWeeks);
Select(btn_ReloadWeekly);
